<?php
declare(strict_types=1); require_once __DIR__.'/auth.php'; require_login(); $pdo=db(); if(!table_exists($pdo,'tasks')) redirect('upgrade_phase2.php'); $msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');$id=post_int('id');if($action==='add'){$title=post_string('title');if($title){$st=$pdo->prepare('INSERT INTO tasks(title,description,assigned_user_id,due_date,priority,status) VALUES(?,?,?,?,?,"open")');$st->execute([$title,post_string('description')?:null,post_int('assigned_user_id')?:null,post_string('due_date')?:null,post_string('priority','normal')]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','tasks',$id,'Task created: '.$title);flash('success','Task created.');}}elseif($action==='complete'){$pdo->prepare('UPDATE tasks SET status="completed",completed_at=NOW() WHERE id=?')->execute([$id]);activity($pdo,'complete','tasks',$id,'Task completed');flash('success','Task completed.');}redirect('tasks.php');}
$users=$pdo->query("SELECT id,first_name,last_name FROM users WHERE status='active' ORDER BY first_name")->fetchAll();$rows=$pdo->query("SELECT t.*,TRIM(CONCAT(COALESCE(u.first_name,''),' ',COALESCE(u.last_name,''))) user_name FROM tasks t LEFT JOIN users u ON u.id=t.assigned_user_id ORDER BY (t.status='completed'), t.due_date, t.id DESC LIMIT 200")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tasks · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1150px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 2fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:#fff;border:0;padding:10px 13px;border-radius:8px;font-weight:bold}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}.done{text-decoration:line-through;color:#7b8490}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Tasks</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="grid"><div class="card"><h2>New Task</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="field"><label>Title</label><input name="title" required></div><div class="field"><label>Description</label><textarea name="description"></textarea></div><div class="field"><label>Assign</label><select name="assigned_user_id"><option value="">Unassigned</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['first_name'].' '.$u['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Due date/time</label><input name="due_date" type="datetime-local"></div><div class="field"><label>Priority</label><select name="priority"><option>low</option><option selected>normal</option><option>high</option><option>urgent</option></select></div><button class="btn">Create Task</button></form></div><div class="card"><h2>Tasks</h2><table class="table"><tr><th>Task</th><th>Assigned</th><th>Priority</th><th>Due</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td class="<?=$r['status']==='completed'?'done':''?>"><?=e($r['title'])?></td><td><?=e(trim($r['user_name'])?:'Unassigned')?></td><td><?=e($r['priority'])?></td><td><?=e($r['due_date']?:'—')?></td><td><?=e($r['status'])?></td><td><?php if($r['status']!=='completed'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="complete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn">Complete</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div></main></body></html>
